// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        // bound amount to a reasonable range
        amount = bound(amount, 0, 10 ether);
        // assume caller and recipient are distinct and not the contract itself to keep it simple
        vm.assume(caller != address(c) && caller != recipient && caller != address(0) && recipient != address(0));
        // fund the contract
        vm.deal(address(c), amount);
        // record balances before the call
        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;
        // try withdrawAll as the fuzzed caller
        bool ok;
        try c.withdrawAll(recipient) {
            // we simulate prank by setting msg.sender inside a try is not straightforward,
            // so we use startPrank/stopPrank in a low-level call wrapper
        } catch {
            // we will handle the prank with a separate approach
        }
        // proper prank-based call:
        vm.startPrank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        vm.stopPrank();
        // after call, read contract balance and recipient balance
        uint256 contractBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;
        // GENERAL RULE: if the caller is the owner, the call must succeed and drain the contract;
        // if the caller is not the owner, the call must revert and the contract balance must remain unchanged.
        // The bug allows any caller to drain, so for caller != owner, contract balance drops to 0 in bug,
        // while reference keeps it unchanged. We assert that when caller != owner, the contract balance is unchanged.
        if (caller != c.owner()) {
            assertTrue(contractBalanceAfter == contractBalanceBefore);
        } else {
            assertTrue(success && contractBalanceAfter == 0);
        }
    }
}

