// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor) public {
        // Ensure the fuzzer tests both owner and non-owner actors
        vm.assume(actor != address(0));

        // Fund the contract so there is something to steal
        address funder = address(0x1000);
        vm.deal(funder, 1 ether);
        vm.prank(funder);
        (bool ok, ) = address(c).call{value: 1 ether}("");
        require(ok, "fund failed");

        uint256 balanceBefore = address(c).balance;

        address recipient = address(this);
        bool success;
        vm.prank(actor);
        try c.withdrawAll(recipient) {
            success = true;
        } catch {
            success = false;
        }

        uint256 balanceAfter = address(c).balance;

        // Rule: if actor != owner, the call must revert OR balance must remain unchanged.
        // For the reference, non-owner calls always revert.
        // For the mutant, non-owner calls succeed and drain the balance.
        if (actor == c.owner()) {
            // Owner call: reference and mutant both succeed; no violation here.
            assertTrue(success);
        } else {
            // Non-owner call: reference reverts -> success==false, balance unchanged.
            // Mutant succeeds -> success==true AND balance decreased.
            // So the invariant is: if success is true, balance must have decreased
            // only for owner, but for non-owner success must be false.
            // Formulate universally: actor != owner => (success == false) && (balanceAfter == balanceBefore)
            assertTrue((!success) && (balanceAfter == balanceBefore));
        }
    }
}

