pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(this));
        vm.assume(recipient != address(c));
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(recipient) {} catch {}
        uint256 balAfter = address(c).balance;
        if (caller == address(this)) {
            assertTrue(balBefore == balAfter || balAfter == 0);
        } else {
            assertEq(balBefore, balAfter);
        }
    }
}

